function meas_out = mfun_smvhz_get_measurement(i_s_abc, u_dc, p)
%MFUN_SMVHZ_GET_MEASUREMENT Block get_measurement of the control system.
%   Generated by motulator_export from the MATLAB port of motulator; the MATLAB Function
%   block of a model contains a copy of this file. The parameters are the fields of the
%   struct p, the struct of the block in the struct ctrl_par of the parameters of the
%   blocks of its control system (e.g., ctrl_par.SpeedController, see the function of
%   the parameters of the control system, e.g., fvc_params; [] as NaN).
% Measurements, the DC-bus voltage limited to U_DC_MIN = 1 V
meas = struct( ...
    'i_c_ab', abc2complex(i_s_abc), ...
    'u_dc', max(u_dc, 1), ...
    'theta_M', 0.0);
meas_out = measurements_pack(meas);
end

function y = measurements_pack(s)
%MEASUREMENTS_PACK Signal vector of the struct s.
y = [ ...
    real(s.i_c_ab);
    imag(s.i_c_ab);
    s.u_dc;
    s.theta_M];
end

function u_ab = abc2complex(u)
%ABC2COMPLEX Space vector from the phase quantities u = [u_a u_b u_c].
u_ab = (2/3)*u(1) - (u(2) + u(3))/3 + 1i*(u(2) - u(3))/sqrt(3);
end
